import time

import jwt
import pytest

from app.core.config import settings
from app.core.security import create_token, hash_password, verify_password


def test_hash_is_bcrypt_cost_12_and_verifies():
    hashed = hash_password("password123")

    assert hashed.startswith("$2b$12$")
    assert verify_password("password123", hashed)
    assert not verify_password("wrong-password", hashed)


def test_verifies_a_hash_made_by_bcryptjs_in_the_express_backend():
    # Generated by bcryptjs.hashSync("password123", 12) in backend-express (ADR-0006: shared users).
    express_hash = "$2b$12$s.FBWp8TTEGeaqBzCFfBY.A9/UIym.F3dCjXGujiG/Y65JPR/3cPW"

    assert verify_password("password123", express_hash)
    assert not verify_password("password124", express_hash)


def test_long_multibyte_passwords_are_truncated_to_72_bytes_like_bcryptjs():
    password = "é" * 72  # 72 characters but 144 bytes; bcrypt 5 raises on > 72 bytes

    hashed = hash_password(password)

    assert verify_password(password, hashed)
    assert verify_password("é" * 36 + "anything after byte 72", hashed)


def test_token_is_hs256_with_sub_role_and_seven_day_expiry():
    token = create_token("6723a1f0c2a4b1e5d0a10001", "user")

    header = jwt.get_unverified_header(token)
    payload = jwt.decode(token, settings.jwt_secret, algorithms=["HS256"])

    assert header["alg"] == "HS256"
    assert payload["sub"] == "6723a1f0c2a4b1e5d0a10001"
    assert payload["role"] == "user"
    assert payload["exp"] - payload["iat"] == 7 * 24 * 60 * 60
    assert abs(payload["iat"] - time.time()) < 5


def test_settings_reject_a_short_jwt_secret():
    from pydantic import ValidationError

    from app.core.config import Settings

    with pytest.raises(ValidationError):
        Settings(jwt_secret="short")
